-- All fixtures and DDL tests are rolled back by the caller.
CREATE TEMP TABLE idea_learning_checks(name text,passed boolean);
GRANT SELECT,INSERT ON idea_learning_checks TO authenticated;
CREATE FUNCTION pg_temp.reject_idea740(q text) RETURNS boolean LANGUAGE plpgsql AS $$BEGIN BEGIN EXECUTE q;EXCEPTION WHEN OTHERS THEN RETURN true;END;RAISE EXCEPTION 'Expected rejection';END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT id FROM auth.users LIMIT 1),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
WITH s AS(INSERT INTO public.trading_sessions(session_date,status) VALUES(current_date,'open') RETURNING id) SELECT set_config('tt740.s',id::text,true) FROM s;
WITH i AS(INSERT INTO public.trade_ideas_v733(session_id,setup_type,instrument,direction,thesis,trigger_condition,invalidation,target_zone) VALUES(current_setting('tt740.s')::uuid,'Momentum','MNQ','long','TEST740','Absorption','Zone gebrochen','Nächste Zone') RETURNING id) SELECT set_config('tt740.i',id::text,true) FROM i;
INSERT INTO idea_learning_checks SELECT 'server captures target time',target_recorded_at IS NOT NULL FROM public.trade_ideas_v733 WHERE id=current_setting('tt740.i')::uuid;
INSERT INTO idea_learning_checks VALUES('original target immutable',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set target_zone=%L where id=%L','Anderer Bereich',current_setting('tt740.i'))));
SELECT set_config('tt740.r','{"outcome":"confirmed","participation":"none","reasons":["missed_trigger"],"note":"Ziel vor Invalidation erreicht, Trigger verpasst.","trigger_followed":"na","risk_followed":"na"}',true);
UPDATE public.trade_ideas_v733 SET learning_review=current_setting('tt740.r')::jsonb,status='completed' WHERE id=current_setting('tt740.i')::uuid AND learning_revision=0;
INSERT INTO idea_learning_checks SELECT 'review server timestamp and revision',learning_revision=1 AND learning_reviewed_at IS NOT NULL FROM public.trade_ideas_v733 WHERE id=current_setting('tt740.i')::uuid;
WITH changed AS(UPDATE public.trade_ideas_v733 SET learning_review=jsonb_set(current_setting('tt740.r')::jsonb,'{note}','"Konkurrierender Entwurf"') WHERE id=current_setting('tt740.i')::uuid AND learning_revision=0 RETURNING id) INSERT INTO idea_learning_checks SELECT 'stale revision updates no row',count(*)=0 FROM changed;
INSERT INTO idea_learning_checks VALUES('reject unknown reason',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set learning_review=jsonb_set(learning_review,%L,%L) where id=%L','{reasons}','["made_up"]',current_setting('tt740.i'))));
INSERT INTO idea_learning_checks VALUES('reject blank evidence',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set learning_review=jsonb_set(learning_review,%L,%L) where id=%L','{note}','""',current_setting('tt740.i'))));
INSERT INTO idea_learning_checks VALUES('reject unknown review fields',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set learning_review=learning_review||%L::jsonb where id=%L','{"invented":true}',current_setting('tt740.i'))));
WITH i AS(INSERT INTO public.trade_ideas_v733(session_id,setup_type,instrument,direction,thesis,trigger_condition,invalidation) VALUES(current_setting('tt740.s')::uuid,'Momentum','MNQ','long','LEGACY740','Absorption','Zone gebrochen') RETURNING id) SELECT set_config('tt740.old',id::text,true) FROM i;
INSERT INTO idea_learning_checks VALUES('legacy without target cannot be confirmed',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set learning_review=%L::jsonb where id=%L',current_setting('tt740.r'),current_setting('tt740.old'))));
WITH a AS(INSERT INTO public.trading_accounts(account_name,account_type,default_instrument,default_quantity) VALUES('TEMP_IDEA740','demo','MNQ',1) RETURNING id) SELECT set_config('tt740.a',id::text,true) FROM a;
UPDATE public.trading_sessions SET htf_context=jsonb_build_object('selected_accounts',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt740.a')))) WHERE id=current_setting('tt740.s')::uuid;
SELECT set_config('tt740.alloc',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt740.a'),'role','leader','instrument','MNQ','planned_quantity',1,'initial_sl_ticks',40))::text,true);
SELECT set_config('tt740.plan','{"thesis":"TEST740 atomic","trigger_condition":"Trigger","invalidation":"Bruch","target_zone":"Zielzone 740"}',true);
SELECT set_config('tt740.req',gen_random_uuid()::text,true);
SELECT set_config('tt740.trade',public.record_trade_attempt_v736(current_setting('tt740.s')::uuid,'TEST','MNQ','long',current_setting('tt740.alloc')::jsonb,'unreported',current_setting('tt740.req')::uuid,'Temporäre Testausnahme',null,null,'{"execution_mode":"independent","emotion_scales":{}}',current_setting('tt740.plan')::jsonb)::text,true);
INSERT INTO idea_learning_checks SELECT 'target and initial risk captured atomically before entry',i.target_zone='Zielzone 740' AND i.target_recorded_at<=t.entry_at AND t.initial_risk_usd=20 FROM public.trade_ideas_v733 i JOIN public.trade_attempts_v733 a ON a.idea_id=i.id JOIN public.trades t ON t.id=a.trade_id WHERE i.id=current_setting('tt740.req')::uuid;
INSERT INTO idea_learning_checks VALUES('entry retry preserves target and trade',public.record_trade_attempt_v736(current_setting('tt740.s')::uuid,'TEST','MNQ','long',current_setting('tt740.alloc')::jsonb,'unreported',current_setting('tt740.req')::uuid,'Temporäre Testausnahme',null,null,'{"execution_mode":"independent","emotion_scales":{}}',current_setting('tt740.plan')::jsonb)=current_setting('tt740.trade')::uuid);
INSERT INTO idea_learning_checks VALUES('open attempt blocks final idea review',pg_temp.reject_idea740(format('update public.trade_ideas_v733 set learning_review=%L::jsonb,status=%L where id=%L',current_setting('tt740.r'),'completed',current_setting('tt740.req'))));
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
INSERT INTO idea_learning_checks SELECT 'other owner cannot read idea',not exists(select 1 from public.trade_ideas_v733 where id=current_setting('tt740.i')::uuid);
WITH changed AS(UPDATE public.trade_ideas_v733 SET learning_review='{}'::jsonb WHERE id=current_setting('tt740.i')::uuid RETURNING id) INSERT INTO idea_learning_checks SELECT 'other owner cannot update idea',count(*)=0 FROM changed;
RESET ROLE;
DO $$BEGIN IF EXISTS(SELECT 1 FROM idea_learning_checks WHERE passed IS NOT TRUE) THEN RAISE EXCEPTION 'Idea learning checks failed';END IF;END $$;
SELECT jsonb_agg(jsonb_build_object('test',name,'passed',passed)) as checks FROM idea_learning_checks;
